document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[el.dataset.icon]||paths.house}"/></svg>`});
const whatsapp='https://wa.me/554599883622?text='+encodeURIComponent('Olá! Gostaria de solicitar um orçamento para meu projeto.');
document.querySelectorAll('.whatsapp').forEach(a=>{a.href=whatsapp;a.target='_blank';a.rel='noopener noreferrer'});
document.getElementById('year').textContent=new Date().getFullYear();
const projects=[['Condomínio Monte Grappa','Residencial','Residenciais Fachadas','project-1.jpg'],['Edifício comercial','Fachada moderna','Comerciais Fachadas','project-2.jpg'],['Imobiliária Kazavel','Fachada comercial','Comerciais Fachadas','project-3.jpg'],['Hotel','Fachada e execução','Comerciais Fachadas','project-4.jpg'],['Comércio em Cascavel','Fachada comercial','Comerciais Fachadas Reformas','project-5.jpg'],['Pintura de fachada','Reforma e acabamento','Fachadas Reformas','project-6.jpg']];
const grid=document.getElementById('project-grid');const dialog=document.getElementById('project-dialog');
function renderProjects(){grid.replaceChildren();projects.forEach(([title,,,image])=>{const button=document.createElement('button');button.className='project-card';button.innerHTML=`<img src="assets/${image}" alt="${title}" loading="lazy">`;button.setAttribute('aria-label',`Ver projeto: ${title}`);button.addEventListener('click',()=>{document.getElementById('dialog-image').src=`assets/${image}`;document.getElementById('dialog-image').alt=title;dialog.showModal()});grid.append(button)})}
renderProjects();
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const range=document.getElementById('comparison-range');function compare(value){range.value=value;document.querySelector('.comparison').style.setProperty('--split',value+'%')}range.addEventListener('input',()=>compare(range.value));document.getElementById('show-before').addEventListener('click',()=>compare(100));document.getElementById('show-after').addEventListener('click',()=>compare(0));
const reviews=[['Juliana Martins','Excelente trabalho! A Surreal cumpriu o prazo, com muita qualidade e profissionalismo. Recomendo de olhos fechados!'],['Ricardo Almeida','Fizeram a reforma da nossa casa e o resultado ficou incrível. Equipe atenciosa e muito competente.'],['Carlos Henrique','Profissionais sérios e comprometidos. Desde o orçamento até a entrega, tudo muito bem organizado.']];let reviewOffset=0;function renderReviews(){document.getElementById('review-cards').innerHTML=reviews.map((_,i)=>{const index=(i+reviewOffset+reviews.length)%reviews.length;const [name,quote]=reviews[index];return `<article class="review-card"><div class="review-heading"><span class="stars" aria-label="5 de 5 estrelas">★★★★★</span></div><blockquote>“${quote}”</blockquote><strong>${name}</strong><small>Cascavel - PR</small></article>`}).join('')}renderReviews();document.getElementById('previous-review').addEventListener('click',()=>{reviewOffset=(reviewOffset+reviews.length-1)%reviews.length;renderReviews()});document.getElementById('next-review').addEventListener('click',()=>{reviewOffset=(reviewOffset+1)%reviews.length;renderReviews()});
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('navigation');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');menu.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');menu.textContent='☰'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open'))menu.click()});
const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id))}}},{rootMargin:'-10% 0px -65% 0px',threshold:0});document.querySelectorAll('#inicio,#sobre,#servicos,#projetos,#depoimentos,#faq,#contato').forEach(s=>observer.observe(s));
if(window.matchMedia('(prefers-reduced-motion: no-preference)').matches){const rise=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.add('shown');rise.unobserve(entry.target)}}},{threshold:.12});document.querySelectorAll('.section,.about,.differences,.contact,footer').forEach(el=>{el.classList.add('reveal');rise.observe(el)})}
